(async () => {
'use strict';
let data=window.DANGERIONS_DATA;
if(location.protocol==='https:'||location.protocol==='http:'){
  const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),6500);
  try {
    const response=await fetch('https://raw.githubusercontent.com/KevinNamini/dangerions-atiel/main/data/history.json?t='+Math.floor(Date.now()/300000),{signal:controller.signal,cache:'no-store'});
    if(!response.ok)throw new Error('Observation feed unavailable');
    const fresh=await response.json();
    if(fresh.guild!=='Dangerions'||!Array.isArray(fresh.players)||fresh.players.length!==7||!Array.isArray(fresh.history)||!fresh.history.length)throw new Error('Invalid observations');
    const names=new Set(data.players.map(p=>p.name));
    if(fresh.players.some(p=>!names.has(p.name)||!Number.isFinite(p.itemLevel)||p.itemLevel<=0||!/^assets\/[A-Za-z0-9]+\.(png|svg)$/.test(p.avatar)||!/^#[a-f0-9]{6}$/i.test(p.color)))throw new Error('Invalid character values');
    if(Date.parse(fresh.updatedAt)>=Date.parse(data.updatedAt))data=fresh;
  }catch(error){data={...data,feedUnavailable:true};}
  finally{clearTimeout(timeout);}
}
if(!data?.players?.length){document.getElementById('update-label').textContent='Charakterdaten derzeit nicht verfügbar';return;}
const $=id=>document.getElementById(id),n=v=>new Intl.NumberFormat('de-DE').format(v),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const dayOf=d=>new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Berlin',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(d));
const formatDay=d=>new Date(d+'T12:00:00Z').toLocaleDateString('de-DE',{day:'2-digit',month:'2-digit',year:'numeric',timeZone:'Europe/Berlin'});
const shortDay=d=>new Date(d+'T12:00:00Z').toLocaleDateString('de-DE',{day:'2-digit',month:'2-digit',timeZone:'Europe/Berlin'});
function previousDay(day){const d=new Date(day+'T12:00:00Z');d.setUTCDate(d.getUTCDate()-1);return d.toISOString().slice(0,10)}
const players=[...data.players].sort((a,b)=>b.itemLevel-a.itemLevel||a.name.localeCompare(b.name,'de'));
const history=[...data.history].sort((a,b)=>a.day.localeCompare(b.day));
const currentDay=history.at(-1)?.day||dayOf(data.updatedAt);
const prev=history.find(h=>h.day===previousDay(currentDay));
const rank=p=>1+players.filter(q=>q.itemLevel>p.itemLevel).length;
function delta(p){const before=prev?.values[p.name];return before&&dayOf(p.observedAt)===currentDay?p.itemLevel-before.itemLevel:null;}
function deltaHTML(p){const d=delta(p);if(d===null)return '<span class="delta neutral">Kein Vergleich<small>Kein Vortagswert</small></span>';if(d===0)return '<span class="delta neutral">— Unverändert<small>zum Vortag</small></span>';return `<span class="delta ${d<0?'down':''}">${d>0?'↑ +':'↓ '}${n(d)}<small>zum Vortag</small></span>`;}
const glyphs={ranger:'<path d="M5 3c10 1 13 7 14 16M5 3l14 16M5 3c-2 8 3 16 14 16M3 21 21 3M14 3h7v7"/>',gladiator:'<path d="m5 19 2-4L17 3l4-1-1 4L9 17l-4 2ZM4 14l6 6M3 21l3-3M15 14l5 6M17 17l4 4"/>',templar:'<path d="m12 2 8 3v7c0 5-8 10-8 10S4 17 4 12V5l8-3ZM12 5v13M8 9h8"/>',cleric:'<path d="M12 2v20M2 12h20M6 6l12 12M6 18 18 6M9 9h6v6H9Z"/>',spiritmaster:'<path d="M12 2c-5 5 2 8-2 11-2-2-3-3-3-6-6 5-3 14 5 15 8-1 12-11 3-16 1 4-2 6-2 6 1-4-2-6-1-10Z"/>',chanter:'<path d="M12 8v14M7 5l5-3 5 3-5 5-5-5ZM5 12h14M8 17h8"/>'};
function icon(p){return `<svg class="class-icon" viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="${esc(p.color)}" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round">${glyphs[p.classKey]||glyphs.gladiator}</svg>`;}
function image(p,cls='portrait'){return `<img class="${cls}" src="${esc(p.avatar)}" alt="${esc(p.name)} – ${p.avatarType==='class'?'Klassensymbol (kein Porträt verfügbar)':'Aion-Charakterporträt'}" loading="lazy">`;}
const top=[players[1],players[0],players[2]].filter(Boolean);
$('podium').innerHTML=top.map(p=>{const r=rank(p),style=r===1?'first':r===2?'second':'third';return `<button class="podium-card ${style}" data-player="${esc(p.name)}" aria-label="${esc(p.name)}, Rang ${r}, Item-Level ${p.itemLevel}. Profil öffnen"><div class="top-rank">${r===1?'I':r===2?'II':'III'}</div>${r===1?'<div class="crown">✦ THRON DER LEGION ✦</div>':''}<div class="portrait-ring">${image(p)}</div><h2 class="podium-name">${esc(p.name)}</h2><div class="podium-class">${icon(p)}<span>${esc(p.className)}</span><b>LV. ${p.level}</b></div><div class="podium-value">${n(p.itemLevel)}</div><div class="value-label">ITEM-LEVEL</div><p class="card-guild">✦ DANGERIONS ✦</p></button>`}).join('');
$('roster').innerHTML=players.map((p,i)=>`<div role="button" tabindex="0" class="rank-row ${i===0?'leader':''} ${p.name==='NaminiLee'?'mine':''}" style="--power:${p.itemLevel/players[0].itemLevel*100}%;--class-color:${p.color}" data-player="${esc(p.name)}" aria-label="Rang ${rank(p)}: ${esc(p.name)}, ${esc(p.className)}, Level ${p.level}, Item-Level ${p.itemLevel}. Profil öffnen"><span class="rank-num">${String(rank(p)).padStart(2,'0')}</span><div class="rank-person"><div class="rank-avatar">${image(p)}</div><div><div class="rank-name">${esc(p.name)}</div><div class="rank-meta">${icon(p)}<span>${esc(p.className)}</span><span class="level">LV. ${p.level}</span></div></div></div><div class="rank-il">${n(p.itemLevel)}<small>${i===0?'Spitze der Legion':n(players[i-1].itemLevel-p.itemLevel)+' bis zum Vordermann'}</small></div>${deltaHTML(p)}<span class="profile-open" aria-hidden="true">↗</span></div>`).join('');
const updated=new Date(data.updatedAt);
const age=(Date.now()-updated.getTime())/36e5;
const updateText=`Stand ${updated.toLocaleDateString('de-DE',{day:'2-digit',month:'2-digit',timeZone:'Europe/Berlin'})} · ${updated.toLocaleTimeString('de-DE',{hour:'2-digit',minute:'2-digit',timeZone:'Europe/Berlin'})} Uhr${age>24?' · älter als 24 Std.':''}`;
$('update-label').textContent=updateText;$('freshness').textContent='Quelle: Öffentliche Aion-Charakterprofile';$('roster-count').textContent=String(players.length);
if(data.feedUnavailable)$('freshness').textContent='Letzter gespeicherter Stand · neuer Abruf derzeit nicht möglich';
if(data.failures?.length){$('freshness').textContent='Teilweise ältere Werte: '+data.failures.map(f=>f.name).join(', ');}
function setView(cards){$('roster').classList.toggle('cards',cards);document.querySelector('.rank-columns').hidden=cards;[$('view-list'),$('view-cards')].forEach((b,i)=>{b.classList.toggle('active',!!i===cards);b.setAttribute('aria-pressed',String(!!i===cards))})}
$('view-list').onclick=()=>setView(false);$('view-cards').onclick=()=>setView(true);
let period=7,selected='all';
$('chart-select').innerHTML=`<button class="player-chip active" data-chart="all" aria-pressed="true">Alle Daevas</button>`+players.map(p=>`<button class="player-chip" data-chart="${esc(p.name)}" style="--chip-color:${p.color}" aria-pressed="false"><i></i>${esc(p.name)}</button>`).join('');
function renderChart(){const cutoff=new Date(currentDay+'T12:00:00Z');cutoff.setUTCDate(cutoff.getUTCDate()-(period-1));const days=history.filter(h=>h.day>=cutoff.toISOString().slice(0,10));const chosen=selected==='all'?players:players.filter(p=>p.name===selected);const points=chosen.flatMap(p=>days.map(h=>h.values[p.name]?.itemLevel).filter(v=>v!=null));if(!points.length){$('chart').innerHTML='<p class="empty-chart">Für diesen Daeva fehlen Messwerte im gewählten Zeitraum.</p>';$('days-tag').textContent='KEIN STAND';$('chart-note').textContent='Wähle einen anderen Zeitraum oder Spieler.';return}const max=Math.ceil(Math.max(...points,100)*1.15/100)*100;const min=selected==='all'?0:Math.max(0,Math.floor(Math.min(...points)*.8/100)*100);const w=660,h=235,left=47,right=65,top=22,bottom=30,plotW=w-left-right,plotH=h-top-bottom;
const stamp=day=>Date.parse(day+'T12:00:00Z');const span=days.length>1?stamp(days.at(-1).day)-stamp(days[0].day):0;const x=(idx)=>!span?left+plotW/2:left+(stamp(days[idx].day)-stamp(days[0].day))/span*plotW;const y=v=>top+plotH-(v-min)/(max-min||1)*plotH;
let svg=`<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="Item-Level-Verlauf, ${days.length} erfasste Tage${days.length<2?'. Heute liegt nur der Startwert vor.':''}"><defs><linearGradient id="chartfill" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#d7b879" stop-opacity=".15"/><stop offset="1" stop-color="#d7b879" stop-opacity="0"/></linearGradient></defs>`;
for(let i=0;i<=4;i++){let v=min+(max-min)*i/4;svg+=`<line x1="${left}" y1="${y(v)}" x2="${w-right}" y2="${y(v)}" stroke="#aeb8c5" stroke-opacity=".10" stroke-dasharray="3 5"/><text x="${left-12}" y="${y(v)+3}" text-anchor="end" fill="#66727f" font-size="9">${n(Math.round(v))}</text>`}
if(days.length===1)svg+=`<line x1="${x(0)}" y1="${top}" x2="${x(0)}" y2="${h-bottom}" stroke="#d7b879" stroke-opacity=".15" stroke-dasharray="3 5"/><text x="${x(0)+80}" y="${top+plotH/2-10}" fill="#67737f" font-size="10">Der erste Meilenstein.</text><text x="${x(0)+80}" y="${top+plotH/2+6}" fill="#54606d" font-size="9">Die Geschichte beginnt hier.</text>`;
chosen.forEach(p=>{let runs=[],run=[];days.forEach((d,i)=>{if(i>0&&stamp(d.day)-stamp(days[i-1].day)>86400000&&run.length){runs.push(run);run=[]}if(d.values[p.name])run.push([x(i),y(d.values[p.name].itemLevel),d.values[p.name].itemLevel,d.day]);else if(run.length){runs.push(run);run=[]}});if(run.length)runs.push(run);runs.forEach(a=>{if(a.length>1){const path=a.map((v,i)=>`${i?'L':'M'}${v[0]},${v[1]}`).join(' ');if(chosen.length===1)svg+=`<path d="${path} L${a.at(-1)[0]},${h-bottom} L${a[0][0]},${h-bottom}Z" fill="url(#chartfill)"/>`;svg+=`<path d="${path}" fill="none" stroke="${p.color}" stroke-width="2" stroke-linecap="round"/>`;}a.forEach(v=>{svg+=`<circle cx="${v[0]}" cy="${v[1]}" r="8" fill="${p.color}" fill-opacity=".1"/><circle cx="${v[0]}" cy="${v[1]}" r="3.5" fill="${p.color}" stroke="#111820" stroke-width="1"><title>${esc(p.name)} · ${formatDay(v[3])} · ${n(v[2])} Item-Level</title></circle>`;if(chosen.length===1||chosen.length<=3)svg+=`<text x="${v[0]}" y="${v[1]-13}" text-anchor="middle" fill="${p.color}" font-size="10">${n(v[2])}</text>`})})});
days.forEach((d,i)=>{if(days.length<8||i===0||i===days.length-1||i%Math.ceil(days.length/5)===0)svg+=`<text x="${x(i)}" y="${h-8}" text-anchor="middle" fill="#7b8690" font-size="9">${shortDay(d.day)}</text>`});svg+='</svg>';
$('chart').innerHTML=svg;$('days-tag').textContent=days.length===1?'TAG 01':`${days.length} TAGE`;$('chart-note').textContent=days.length<2?'Die erste Momentaufnahme ist erfasst. Sobald ein weiterer Tag vorliegt, verbinden sich die Punkte zu eurem echten Verlauf. Wähle einen Daeva für seinen Startwert.':'Jeder Punkt zeigt den zuletzt erfassten Wert des jeweiligen Tages (Europe/Berlin). Fehlende Tage werden nicht erfunden.';}
$('chart-select').addEventListener('click',e=>{const b=e.target.closest('[data-chart]');if(!b)return;selected=b.dataset.chart;document.querySelectorAll('[data-chart]').forEach(c=>{c.classList.toggle('active',c===b);c.setAttribute('aria-pressed',String(c===b))});renderChart()});
document.querySelectorAll('[data-period]').forEach(b=>b.onclick=()=>{period=Number(b.dataset.period);document.querySelectorAll('[data-period]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});renderChart()});renderChart();
const gainers=players.map(p=>({p,d:delta(p)})).filter(o=>o.d!==null&&o.d>0).sort((a,b)=>b.d-a.d);const winner=gainers[0];
$('daily-champion').innerHTML=winner?`<p class="eyebrow">✦ AUFSTEIGER DES TAGES ✦</p>${image(winner.p)}<h3>${esc(winner.p.name)}</h3><strong class="gain">+${n(winner.d)}</strong><p>Item-Level gegenüber dem Vortag${gainers.filter(x=>x.d===winner.d).length>1?' · geteilter Spitzenwert':''}</p>`:prev?'<p class="eyebrow">✦ AUFSTEIGER DES TAGES ✦</p><div class="champion-sigil">◇</div><h3>Die Ruhe vor dem Aufstieg.</h3><p>Unter den vergleichbaren Werten wurde heute noch kein höheres Item-Level erfasst.</p>':'<p class="eyebrow">✦ AUFSTEIGER DES TAGES ✦</p><div class="champion-sigil">♜</div><h3>Die Krone wartet.</h3><p>Der größte Tagesgewinn bekommt hier seinen Platz. Dafür fehlt noch der nächste Tagesstand.</p>';
$('archive-status-text').textContent=data.scheduleEnabled?'Neue Werte werden regelmäßig erfasst. Der letzte Stand pro Tag bleibt für euren Vergleich erhalten.':'Startwerte vom '+formatDay(history[0].day)+'. Weitere Tagesstände werden nach der Einrichtung der automatischen Erfassung ergänzt.';
$('timeline').innerHTML=history.slice(-4).reverse().map(h=>{const before=history.find(q=>q.day===previousDay(h.day));let text,title;if(!before){title=h===history[0]?'Das erste Kapitel ist geschrieben.':'Ein neuer Tagesstand.';text=`${Object.keys(h.values).length} Daevas erfasst. ${h===history[0]?'Ab hier zählt jeder Aufstieg.':'Für diesen Tag liegt kein direkter Vortagsvergleich vor.'}`}else{const changes=players.filter(p=>h.values[p.name]&&before.values[p.name]).map(p=>({name:p.name,d:h.values[p.name].itemLevel-before.values[p.name].itemLevel}));const up=changes.filter(c=>c.d>0),same=changes.filter(c=>c.d===0),down=changes.filter(c=>c.d<0);title=`${up.length} aufgestiegen · ${same.length} unverändert${down.length?' · '+down.length+' gesunken':''}`;text=changes.filter(c=>c.d!==0).map(c=>`${c.name} ${c.d>0?'+':''}${n(c.d)}`).join(' · ')||'Alle vergleichbaren Item-Level sind unverändert.';}return `<article class="timeline-item"><time datetime="${h.day}">${formatDay(h.day)}</time><h4>${esc(title)}</h4><p>${esc(text)}</p></article>`}).join('');
function openPlayer(name){const p=players.find(x=>x.name===name);if(!p)return;const ownHistory=history.filter(h=>h.values[name]).slice(-14).reverse();$('player-detail').innerHTML=`<div class="detail-hero" style="--class-tint:${p.color}12"><p class="eyebrow">DANGERIONS · RANG ${rank(p)}</p>${image(p)}<h2 id="player-dialog-title">${esc(name)}</h2><p>${icon(p)} ${esc(p.className)} · Asmodier · Atiel</p></div><div class="detail-stats"><div><b>${n(p.itemLevel)}</b><span>ITEM-LEVEL</span></div><div><b>${p.level}</b><span>LEVEL</span></div><div><b>${n(p.combatPower)}</b><span>KAMPFKRAFT</span></div></div><div class="detail-body">${deltaHTML(p)}<h3>Letzte Meilensteine</h3>${ownHistory.map(h=>{const v=h.values[name],old=history.find(q=>q.day===previousDay(h.day))?.values[name];const d=old?v.itemLevel-old.itemLevel:null;return `<div class="detail-history"><span>${formatDay(h.day)}</span><strong>${n(v.itemLevel)} IL</strong><span style="color:${d>0?'#9bc7aa':d<0?'#d69e8c':'#8a939e'}">${d===null?'Kein Vortagswert':d===0?'±0':(d>0?'+':'')+n(d)}</span></div>`}).join('')}<p class="detail-note">Zuletzt beobachtet: ${new Date(p.observedAt).toLocaleString('de-DE',{timeZone:'Europe/Berlin'})} Uhr. Die Kampfkraft beeinflusst den Rang nicht.${p.guild!=='Dangerions'?' Aktuell gemeldete Legion: '+esc(p.guild||'keine')+'.':''}</p><a class="source-link" href="${esc(p.url)}" target="_blank" rel="noopener noreferrer">OFFIZIELLES AION-PROFIL ↗</a></div>`;$('player-dialog').showModal();document.body.style.overflow='hidden';wireFallbacks();}
document.addEventListener('click',e=>{const b=e.target.closest('[data-player]');if(b)openPlayer(b.dataset.player)});document.querySelectorAll('.rank-row').forEach(b=>b.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();openPlayer(b.dataset.player)}});
$('close-dialog').onclick=()=>$('player-dialog').close();$('player-dialog').addEventListener('close',()=>{document.body.style.overflow=''});$('player-dialog').addEventListener('click',e=>{if(e.target===$('player-dialog')){const r=$('player-dialog').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('player-dialog').close()}});
let toastTimer;function toast(message){$('toast').textContent=message;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),3500)}
$('share').onclick=async()=>{if(location.protocol==='file:'){toast('Diese Vorschau ist lokal. Der teilbare Link folgt nach der Veröffentlichung.');return}try{if(navigator.share){await navigator.share({title:'Dangerions · Hall of Ascension',text:'Sieben Daevas. Ein Vermächtnis. Unsere Legionsrangliste.',url:location.href.split('#')[0]})}else{await navigator.clipboard.writeText(location.href.split('#')[0]);toast('Legionslink kopiert. Bereit für eure Gruppe.')}}catch(e){if(e.name!=='AbortError')toast('Link kopieren: '+location.href.split('#')[0])}};
function wireFallbacks(){document.querySelectorAll('img.portrait').forEach(img=>{img.onerror=()=>{const d=document.createElement('span');d.className='card-fallback';d.textContent=img.alt.split(' ')[0].slice(0,2).toUpperCase();d.setAttribute('aria-label',img.alt);img.replaceWith(d)}})}wireFallbacks();
const particles=document.querySelector('.embers');for(let i=0;i<21;i++){const p=document.createElement('i');p.style.left=(5+(i*43)%90)+'%';p.style.top=(20+(i*37)%70)+'%';p.style.animationDelay=-(i*.73)+'s';p.style.animationDuration=(8+i%7)+'s';particles.appendChild(p)}
})();
